  ('Textile  job kori', NULL, 'Shothik Karjokrom', 5, 32),
  ('আমার নাম ইয়াছির আরেফিন তুষার। পেশায় আমি একজন সফটওয়্যার ইঞ্জিনিয়ার। আমেরিকান একটা সফটওয়্যার কোম্পানি তে কর্মরত আছি (remote)।', NULL, 'খুবই ভালো উদ্যোগ।', 5, 33),
  ('পড়াশোনা করতেছি', NULL, 'আপনারা আমাদের জন্য ভালো ভালো কিছু নিয়ে আসছেন আপনাদেরকে ধন্যবাদ আরো যদি ভালো কিছু নিয়ে আসা যায় আর আপনারা কোম্পানিতে থেকে যদি আমাদেরকে আরেকটু কোম্পানি সম্বন্ধে আশ্বস্ত করতে পারেন তাহলে আমরা আরেকটু বিনিয়োগ করতে আরো বেশি ইচ্ছে পোষন করতাম', 5, 34),
  ('ইঞ্জিনিয়ার', NULL, 'আপনাদের এর সার্ভে গুলোর জন্য ভালো লাগে। সুদ মুক্ত বিনিয়োগে আপনাদের এই উদ্যোগ সত্যি প্রশংসার দাবিদার।', 5, 35),
  ('সৌদি আরবের চাকরি করছি', NULL, 'সময়োপযোগী একটা উদ্যোগ', 5, 36),
  ('চাকরি করছি', NULL, 'আপনারা আল্লাহর পক্ষে, সুদের বিপক্ষে যুদ্ধে আছেন বলে আমার বিশ্বাস। হক্কানী আলেমদের পরামর্শ নিয়ে প্রতিষ্ঠানে কি ভাবে আরও দ্বীনি পরিবেশ তৈরি করা যায়, এবং রিভিউ করার সময় যদি আলেমদের কেউ প্যানেলে থাকে, তাহলে আরও আরও চমৎকার হবে ইনশাআল্লাহ। (আমি বিনিয়োগ করতে গিয়ে কোম্পানির ইন্সুরেন্স থাকা নিয়ে দ্বিধাদ্বন্দে পড়েছিলাম, যে এটা হালাল না হারাম।', 5, 37),
  ('Software Engineer', NULL, 'বিনিয়োগ বৃদ্ধির জন্য এটি একটি চমৎকার প্ল্যাটফর্ম। এখানে ইসলামিক নিয়ম অনুসরণ করে বিনিয়োগ করা যায়, ব্যাংকিং সিস্টেমের সুদ ছাড়াই।', 5, 38),
  ('সরজুল', 'জব, 01850670172', 'আমি বিনিয়োগ করেছি কিন্তু আমার এখনও ভয় কাজ করে, কেউ যে েকোন সময়ে প্রতারনা করতে পারে। সেই সুযোগ আছে, যারা টাকা নিচ্ছে।', 5, 39),
